REPO_ROOT = Path(__file__).resolve().parents[1]
GENERATED_CONFIG = REPO_ROOT / "configs" / "engine_generated.toml"
MINUTE = 60_000_000
DAY = 86_400_000_000
ALLOWANCE_US = 250_000
A_US = 10_000_000
LATENCY_US = 500_000
DELAY_US = A_US


def utc(year: int, month: int, day: int, hour: int = 0, minute: int = 0) -> int:
    return to_us(dt.datetime(year, month, day, hour, minute, tzinfo=dt.UTC))


def engine_config() -> EngineConfig:
    return load_engine_config(GENERATED_CONFIG)


def default_only_config(base: Path, *, draws: int | None = None) -> Path:
    """The shipped file, with only the default lines, so a test stays quick. A test may state its draws."""
    text = GENERATED_CONFIG.read_text(encoding="utf-8").replace('lines = "all"', 'lines = "default_only"')
    name = "default_only.toml"
    if draws is not None:
        text = text.replace("draws = 200", f"draws = {draws}")
        name = f"default_only_{draws}.toml"
    path = base / name
    path.write_text(text, encoding="utf-8")
    return path


def costs(rt_bps: float = 12.0, slip_bps: float = 1.0, stop_slip_bps: float = 5.0) -> CostConfig:
    return CostConfig(rt_bps, slip_bps, stop_slip_bps, rt_bps / 2.0 - slip_bps, "test")


def sim_params(
    *,
    latency_us: int = LATENCY_US,
    allowance_us: int = A_US,
    fill_span_allowance_us: int = ALLOWANCE_US,
    risk_budget: float = 250.0,
    capital: float = 100_000.0,
    leverage_cap: float = 2.0,
    tick: float = 0.01,
    cost: CostConfig | None = None,
    span_end_us: int | None = None,
    read_days_us: tuple[tuple[int, int], ...] = (),
) -> SimParams:
    return SimParams(
        costs=costs() if cost is None else cost,
        latency_us=latency_us,
        allowance_us=allowance_us,
        fill_span_allowance_us=fill_span_allowance_us,
        risk_budget=risk_budget,
        capital=capital,
        leverage_cap=leverage_cap,
        tick=tick,
        span_end_us=span_end_us,
        read_days_us=read_days_us,
    )


# ---- a generated market
# -----------------------------------------------------------------------------------------


def generated_trades(
    *,
    seed: int,
    start_us: int,
    days: int = 70,
    per_minute: float = 1.2,
    start_price: float = 1000.0,
    daily_vol: float = 0.03,
    first_id: int = 1000,
) -> pl.DataFrame:
    """Trades on a seeded path. Volatility and drift change by the day, so quiet stretches and legs both
    appear.
    """
    rng = np.random.default_rng(seed)
    minutes = days * 1440
    counts = rng.poisson(per_minute, minutes)
    counts[0] = max(int(counts[0]), 1)
    total = int(counts.sum())
    minute_index = np.repeat(np.arange(minutes, dtype=np.int64), counts)
    offset = rng.integers(1, MINUTE, total, dtype=np.int64)
    stamps = start_us + minute_index * MINUTE + offset
    stamps.sort()
    day_of_trade = ((stamps - start_us) // DAY).astype(np.int64)
    day_vol = np.exp(rng.normal(0.0, 0.45, days))
    day_drift = rng.normal(0.0, 0.5, days)
    step = daily_vol / np.sqrt(per_minute * 1440.0)
    returns = rng.normal(0.0, 1.0, total) * step * day_vol[day_of_trade] + (
        day_drift[day_of_trade] * step * 0.15
    )
    price = np.round(start_price * np.exp(np.cumsum(returns)), 2)
    qty = np.round(rng.uniform(0.001, 3.0, total), 3)
    buys = rng.random(total) < 0.5
    return _trades_from_arrays(stamps, price, qty, buys, first_id=first_id)


def _trades_from_arrays(
    stamps: np.ndarray[Any, Any],
    price: np.ndarray[Any, Any],
    qty: np.ndarray[Any, Any],
    buys: np.ndarray[Any, Any],
    *,
    first_id: int,
    allowance_us: int = ALLOWANCE_US,
) -> pl.DataFrame:
    size = stamps.size
    return pl.DataFrame(
        {
            "ts": pl.Series(stamps, dtype=pl.Int64).cast(UTC_TIME),
            "price": pl.Series(price, dtype=pl.Float64),
            "qty": pl.Series(qty, dtype=pl.Float64),
            "is_taker_buy": pl.Series(buys, dtype=pl.Boolean),
            "trade_id": pl.Series(np.arange(first_id, first_id + size, dtype=np.int64), dtype=pl.Int64),
            "file_row": pl.Series(np.arange(size, dtype=np.int64), dtype=pl.Int64),
            "n_fills": pl.Series(np.ones(size, dtype=np.int32), dtype=pl.Int32),
            "knowable_time": pl.Series(stamps + allowance_us, dtype=pl.Int64).cast(UTC_TIME),
        }
    )


def trades_through(trades: pl.DataFrame, cut_us: int) -> pl.DataFrame:
    return trades.filter(pl.col("ts") <= pl.lit(cut_us, dtype=pl.Int64).cast(UTC_TIME))


def perturb_after(trades: pl.DataFrame, cut_us: int, seed: int) -> pl.DataFrame:
    """Replace everything after the cut with wild noise, with ids that run on from the last row kept."""
    rng = np.random.default_rng(seed)
    kept = trades_through(trades, cut_us)
    last_id = int(str(kept["trade_id"].max()))
    newest = int(str(trades["ts"].dt.timestamp("us").max()))
    count = max(trades.height - kept.height, 200)
    stamps = np.unique(cut_us + rng.integers(1, max(newest - cut_us, 10 * MINUTE) + 1, count, dtype=np.int64))
    size = stamps.size
    noise = _trades_from_arrays(
        stamps,
        np.round(rng.uniform(1.0, 100_000.0, size), 2),
        np.round(rng.uniform(0.001, 500.0, size), 3),
        rng.random(size) < 0.5,
        first_id=last_id + 1,
    )
    return pl.concat([kept.select(noise.columns), noise])


def candles_from(trades: pl.DataFrame, *, first_open_us: int, minutes: int) -> pl.DataFrame:
    """Candles over `[open, open + 60 s)`, so a print exactly on a boundary falls in the later one.

    A minute with no trades carries the last close forward, as a venue may, and reports a count of zero.
    """
    stamps = trades["ts"].dt.timestamp("us").to_numpy()
    prices = trades["price"].to_numpy()
    qty = trades["qty"].to_numpy()
    slots = (stamps - first_open_us) // MINUTE
    keep = (slots >= 0) & (slots < minutes)
    slots, prices, qty = slots[keep], prices[keep], qty[keep]
    order = np.lexsort((np.arange(slots.size), slots))
    slots, prices, qty = slots[order], prices[order], qty[order]
    starts = np.searchsorted(slots, np.arange(minutes), side="left")
    ends = np.searchsorted(slots, np.arange(minutes), side="right")
    rows: dict[str, list[Any]] = {
        key: [] for key in ("open", "high", "low", "close", "volume", "quote_volume", "trade_count")
    }
    last = float(prices[0])
    for begin, end in zip(starts.tolist(), ends.tolist(), strict=True):
        if end > begin:
            chunk = prices[begin:end]
            amount = qty[begin:end]
            rows["open"].append(float(chunk[0]))
            rows["high"].append(float(chunk.max()))
            rows["low"].append(float(chunk.min()))
            rows["close"].append(float(chunk[-1]))
            rows["volume"].append(float(amount.sum()))
            rows["quote_volume"].append(float((chunk * amount).sum()))
            rows["trade_count"].append(int(end - begin))
            last = float(chunk[-1])
        else:
            for key in ("open", "high", "low", "close"):
                rows[key].append(last)
            rows["volume"].append(0.0)
            rows["quote_volume"].append(0.0)
            rows["trade_count"].append(0)
    opens = first_open_us + np.arange(minutes, dtype=np.int64) * MINUTE
    return pl.DataFrame(
        {
            "open_time": pl.Series(opens, dtype=pl.Int64).cast(UTC_TIME),
            **{key: pl.Series(rows[key], dtype=pl.Float64) for key in rows if key != "trade_count"},
            "trade_count": pl.Series(rows["trade_count"], dtype=pl.Int64),
            "taker_buy_volume": pl.Series([value / 2.0 for value in rows["volume"]], dtype=pl.Float64),
        }
    )


def minute_bars(trades: pl.DataFrame, *, first_close_us: int, last_close_us: int) -> pl.DataFrame:
    return build_bars_1m(
        trades,
        venue="generated",
        symbol="S",
        first_close_us=first_close_us,
        last_close_us=last_close_us,
        continuity="trade_id",
        fill_span_allowance_us=ALLOWANCE_US,
        received_at_us=None,
    )


def floor_minute(value_us: int) -> int:
    return value_us // MINUTE * MINUTE


def tape_and_trades(
    trades: pl.DataFrame,
    *,
    start_us: int,
    through_us: int,
    delay_us: int = DELAY_US,
    symbol: str = "S",
) -> tuple[MinuteTape, TradeTape]:
    """Bars and trades as a run would hold them with data through a moment."""
    held = trades_through(trades, through_us)
    last_close = floor_minute(through_us)
    bars = minute_bars(held, first_close_us=start_us + MINUTE, last_close_us=last_close)
    return MinuteTape.from_frame(bars, symbol=symbol, delay_us=delay_us), TradeTape.from_frame(held)


def run_stream(
    strategy_id: str,
    tape: MinuteTape,
    trades: TradeTape | None,
    *,
    params: dict[str, Any] | None = None,
    probe: Callable[[Strategy, MarketView], None] | None = None,
    sim: SimParams | None = None,
) -> StreamResult:
    engine = engine_config()
    merged = {
        **engine.strategies[strategy_id].default().params,
        "tier": "T1" if trades is not None else "T0",
        **(params or {}),
    }
    strategy = build_strategy(strategy_id, merged)
    return Simulator(strategy, tape, sim or sim_params(), trades=trades, probe=probe).run()


def write_generated_root(
    path: Path,
    *,
    first: dt.date = dt.date(2000, 1, 3),
    days: int = 70,
    seed: int = 41,
    venue: str = "synthetic",
    symbols: tuple[str, ...] = ("SYNTHBTC", "SYNTHETH"),
) -> DataRoot:
    """A root holding generated bars and trades, written where the reader looks for them."""
    root = DataRoot(path)
    root.guard.check(SYNTHETIC_MARKER).write_text("Generated test data. Not market data.\n", encoding="utf-8")
    catalog = Catalog(root.catalog_path)
    catalog.set_meta("data_kind", "SYNTHETIC")
    catalog.close()
    start = utc(first.year, first.month, first.day)
    for index, symbol in enumerate(symbols):
        trades = generated_trades(
            seed=seed + index, start_us=start, days=days, start_price=1000.0 if index == 0 else 100.0
        )
        bars = minute_bars(
            trades, first_close_us=start + MINUTE, last_close_us=start + days * DAY
        ).with_columns(pl.lit(venue).alias("venue"), pl.lit(symbol).alias("symbol"))
        for offset in range(days):
            day = first + dt.timedelta(days=offset)
            low = pl.lit(start + offset * DAY, dtype=pl.Int64).cast(UTC_TIME)
            high = pl.lit(start + (offset + 1) * DAY, dtype=pl.Int64).cast(UTC_TIME)
            atomic_write_parquet(
                root.curated_part(BARS_1M, venue, symbol, day),
                bars.filter((pl.col("open_time") >= low) & (pl.col("open_time") < high)),
                guard=root.guard,
            )
            atomic_write_parquet(
                root.curated_part(TRADES, venue, symbol, day),
                trades.filter((pl.col("ts") >= low) & (pl.col("ts") < high)),
                guard=root.guard,
            )
    return root


# ---- a table of bars from a document's worked example
# -----------------------------------------------------------


@dataclass(frozen=True)
class TableBar:
    """One row of a worked example: its close time, and open, high, low, close."""

    close_us: int
    o: float
    h: float
    l: float  # noqa: E741
    c: float
    v: float = 100.0


def rows_from_table(bars: Sequence[TableBar], minutes: int) -> pl.DataFrame:
    """1m rows that aggregate exactly to each bar. The path goes to the far side first on an up close."""
    rows: list[dict[str, Any]] = []
    for bar in bars:
        first_extreme, second_extreme = (bar.l, bar.h) if bar.c >= bar.o else (bar.h, bar.l)
        path = [bar.o, first_extreme, second_extreme, bar.c]
        open_us = bar.close_us - minutes * MINUTE
        for index in range(minutes):
            row_open = open_us + index * MINUTE
            row: dict[str, Any] = {
                "open_time": row_open,
                "close_time": row_open + MINUTE,
                "knowable_time": row_open + MINUTE,
                "gap": False,
            }
            # Four rows carry the path, spread so the last minute of the bar closes it.
            step = {0: 0, 1: 1, 2: 2, minutes - 1: 3}.get(index)
            if step is None:
                row.update(open=None, high=None, low=None, close=None, volume=0.0, trade_count=0)
            else:
                start = path[step - 1] if step else bar.o
                end = path[step]
                row.update(
                    open=start,
                    high=max(start, end),
                    low=min(start, end),
                    close=end,
                    volume=bar.v / 4.0,
                    trade_count=1,
                )
            rows.append(row)
    frame = pl.DataFrame(
        rows,
        schema_overrides={"open": pl.Float64, "high": pl.Float64, "low": pl.Float64, "close": pl.Float64},
    )
    return frame.with_columns(
        pl.col("open_time").cast(pl.Int64).cast(UTC_TIME),
        pl.col("close_time").cast(pl.Int64).cast(UTC_TIME),
        pl.col("knowable_time").cast(pl.Int64).cast(UTC_TIME),
    )


class ExampleSimulator(Simulator):
    """Runs a document's table: indicators held flat as the examples hold them, and one setup injected."""

    def __init__(
        self,
        strategy: Strategy,
        tape: MinuteTape,
        params: SimParams,
        *,
        atr: float | dict[int, float] | None = None,
        vr: float = 1.0,
        srv: float | dict[int, float] = 1.5,
        days_at_close: dict[int, PeriodBar] | None = None,
        days_at_open: dict[int, PeriodBar] | None = None,
        trades: TradeTape | None = None,
        fields: dict[str, Any] | None = None,
    ) -> None:
        super().__init__(strategy, tape, params, trades=trades)
        self._fields = fields or {}
        self._days_open = days_at_open or {}
        self._atr = atr
        self._vr = vr
        self._srv = srv
        self._days = days_at_close or {}

    def _bars(self, minutes: int) -> list[Bar]:
        result = []
        for bar in self.tape.frame(minutes):
            atr = self._atr.get(bar.close_us) if isinstance(self._atr, dict) else self._atr
            srv = self._srv.get(bar.close_us, 1.5) if isinstance(self._srv, dict) else self._srv
            result.append(
                replace(
                    bar,
                    atr=atr,
                    atr_last=atr,
                    vr=self._vr,
                    srv=srv,
                    complete=True,
                    day_at_close=self._days.get(bar.close_us),
                    day=self._days_open.get(bar.close_us),
                    tr=bar.tr if bar.tr is not None else bar.h - bar.l,
                    **self._fields,
                )
            )
        return result


def scripted(base: type[Strategy], params: dict[str, Any], at_close_us: int, proposal: Proposal) -> Strategy:
    """A real strategy, with one setup handed to it at one close, as a worked example starts from."""

    class Scripted(base):  # type: ignore[valid-type, misc]
        def on_close(self, market: MarketView) -> list[Proposal]:
            found: list[Proposal] = super().on_close(market)
            del found
            return [proposal] if market.bar.close_us == at_close_us else []

    return Scripted(params)


def example_params(*, tick: float, risk_budget: float = 1000.0, stop_slip_bps: float = 0.0) -> SimParams:
    """C16's arithmetic, with no delay, as the examples are written in IDEAL terms."""
    return sim_params(
        latency_us=0,
        allowance_us=0,
        fill_span_allowance_us=0,
        tick=tick,
        risk_budget=risk_budget,
        capital=100_000_000.0,
        leverage_cap=1000.0,
        cost=costs(stop_slip_bps=stop_slip_bps),
    )


def stops_after_each_close(stream: StreamResult, closes: Sequence[int], s0: float) -> list[float]:
    """The stop that would act after each close, from the logged path."""
    trade = stream.trades[0]
    result = []
    current = s0
    path = {row["computed_at_us"]: row["new"] for row in trade.stop_path}
    for close in closes:
        current = path.get(close, current)
        result.append(float(current))
    return result


def day_bar(end_us: int, high: float, low: float, close: float) -> PeriodBar:
    return PeriodBar(end_us - DAY, end_us, close, high, low, close)
